// 极致了API配置
const CONFIG = {
  accountName: '饼干哥哥AGI',
  apiKey: 'JZLdc9670be1403c05c',
  baseUrl: 'https://www.dajiala.com/fbmain/monitor/v3/post_history',
  maxPages: 10,  // 每次抓取10页，可自行调整
  delayMs: 1000  // 请求间隔1秒
};

return [{
  json: {
    config: CONFIG,
    currentPage: 1,
    allArticles: [],
    totalCost: 0
  }
}];

const response = $input.first().json;

// API错误处理
if (response.code !== 0) {
  if (response.code === 110) {
    console.log('✅ 翻页结束，没有更多文章');
    return [{json: {...$input.first().json, hasMore: false, endReason: 'no_more_pages'}}];
  }
  if (response.code === 115) {
    console.log('✅ 后续页面文章已全部删除');
    return [{json: {...$input.first().json, hasMore: false, endReason: 'all_deleted'}}];
  }
  throw new Error(`API错误 [${response.code}]: ${response.msg}`);
}

const articles = response.data || [];
const totalPage = response.total_page || 1;
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];
const maxPages = $input.first().json.config.maxPages;

// 去重检查（基于appmsgid）
const existingIds = new Set(allArticles.map(a => a.appmsgid));
const newArticles = articles.filter(a => !existingIds.has(a.appmsgid));
allArticles.push(...newArticles);

// 更新总费用
const totalCost = ($input.first().json.totalCost || 0) + (response.cost_money || 0);

// 判断是否继续
const hasMore = currentPage < Math.min(totalPage, maxPages);
const progress = Math.round((currentPage / Math.min(totalPage, maxPages)) * 100);

console.log(`✅ 第 ${currentPage}/${totalPage} 页: ${articles.length} 篇文章 (新增 ${newArticles.length} 篇)`);
console.log(`📊 进度: ${progress}% | 累计: ${allArticles.length} 篇 | 费用: ${totalCost.toFixed(2)}元`);
console.log(`💰 余额: ${response.remain_money}元`);

return [{
  json: {
    ...$input.first().json,
    articles: newArticles,
    allArticles,
    totalPages: totalPage,
    hasMore,
    nextPage: currentPage + 1,
    progress,
    totalCost,
    remainMoney: response.remain_money,
    accountInfo: {
      nickname: response.mp_nickname,
      wxid: response.mp_wxid,
      ghid: response.mp_ghid,
      totalNum: response.total_num,
      publishCount: response.publish_count,
      masssendCount: response.masssend_count
    }
  }
}];

// 构建最终输出
const data = $input.first().json;
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

const output = {
  metadata: {
    accountName: data.config.accountName,
    fetchTime: new Date().toISOString(),
    totalPages: data.totalPages,
    fetchedPages: data.currentPage - 1,
    totalArticles: data.allArticles.length,
    totalCost: data.totalCost,
    remainMoney: data.remainMoney,
    accountInfo: data.accountInfo
  },
  articles: data.allArticles.map((article, index) => ({
    index: index + 1,
    title: article.title,
    url: article.url,
    publishTime: article.post_time_str,
    timestamp: article.post_time,
    digest: article.digest,
    coverUrl: article.cover_url,
    isOriginal: article.original === 1,
    isOriginalText: article.original === 1 ? '原创' : article.original === 2 ? '转载' : '未声明',
    position: article.position,
    positionText: ['', '头条', '二条', '三条', '四条', '五条', '六条', '七条', '八条'][article.position] || article.position,
    type: article.item_show_type === 0 ? '图文' : article.item_show_type === 5 ? '视频' : article.item_show_type === 10 ? '文字' : '其他',
    status: article.msg_status === 2 ? '正常' : article.msg_status === 7 ? '已删除' : '异常',
    appmsgid: article.appmsgid
  }))
};

console.log(`🎉 抓取完成! 共 ${output.articles.length} 篇文章`);
console.log(`💰 总费用: ${output.metadata.totalCost.toFixed(2)}元`);

return [{json: output}];
